// One palette, two engines. shared/palette.json is the source of truth:
// Remotion imports it directly; this writes the same values as CSS variables for HyperFrames.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const palette = JSON.parse(readFileSync(join(ROOT, "shared", "palette.json"), "utf8"));
const kebab = (s) => s.replace(/[A-Z]/g, (m) => "-" + m.toLowerCase());
const css =
  "/* Generated by scripts/sync-palette.mjs from shared/palette.json. Do not edit. */\n:root {\n" +
  Object.entries(palette)
    .map(([k, v]) => `  --pc-${kebab(k)}: ${v};`)
    .join("\n") +
  "\n}\n";
writeFileSync(join(ROOT, "hyperframes", "assets", "palette.css"), css);
console.log(css);
